    "pseudocode": "FUNCTION evaluate_network_outage_impact_estimator(tower_site_id, cells_down_count, registered_subscribers, overlap_site_coverage_pct, tier1_enterprise_links):\n    // -------------------------------------------------------------------------\n    // SYSTEM GOAL: Network Outage Impact Estimator (Telecom, Media & Digital Platforms)\n    // CONSTRAINT RULE: Avoid double-counting customers served by overlapping network elements.\n    // -------------------------------------------------------------------------\n    \n    // STEP 1: Input Integrity & Null/Boundary Validation\n    FOR EACH parameter IN [tower_site_id, cells_down_count, registered_subscribers, overlap_site_coverage_pct, tier1_enterprise_links]:\n        IF parameter IS NULL OR parameter IS UNDEFINED THEN\n            LOG_EVENT(\"AUDIT_WARN\", \"Missing telemetric or transactional signal\", parameter)\n            RETURN {\"status\": \"SEV2_DEGRADED_FAILOVER\", \"reason\": \"Missing required field: \" + parameter, \"flag_manual\": TRUE}\n        END IF\n    END FOR\n\n    // STEP 2: Parameter Range & Outlier Sanitization\n    INITIALIZE risk_score = 0\n    INITIALIZE decision_notes = []\n    \n    // Domain-Specific Decision Tree\n    IF tower_site_id <= 0 THEN\n        RETURN {\"status\": \"INVALID_INPUT\", \"reason\": \"Primary metric value non-positive\", \"score\": 0}\n    END IF\n\n    // STEP 3: Rule Evaluation & Threshold Gating\n    IF cells_down_count == TRUE OR cells_down_count > 75 THEN\n        risk_score = risk_score + 40\n        APPEND \"High variance/anomaly detected on primary secondary metric\" TO decision_notes\n    END IF\n    IF registered_subscribers IS NOT NULL AND registered_subscribers > 50 THEN\n        risk_score = risk_score + 35\n        APPEND \"Elevated stress metric detected\" TO decision_notes\n    END IF\n    // STEP 4: Guardrail Enforcement (Respecting Real-World Constraint)\n    // Mandatory verification: \"Avoid double-counting customers served by overlapping network elements.\"\n    \n    IF risk_score >= 70 THEN\n        LOG_EVENT(\"ACTION_ESCALATE\", \"Upper critical threshold crossed\", risk_score)\n        RETURN {\n            \"decision\": \"INCIDENT_AUTO_NOTIFIED\",\n            \"score\": risk_score,\n            \"evidence\": decision_notes,\n            \"requires_human_signoff\": TRUE,\n            \"timestamp\": CURRENT_TIMESTAMP()\n        }\n    ELSE IF risk_score >= 35 THEN\n        LOG_EVENT(\"ACTION_REVIEW\", \"Medium risk tier identified\", risk_score)\n        RETURN {\n            \"decision\": \"SEV2_DEGRADED_FAILOVER\",\n            \"score\": risk_score,\n            \"evidence\": decision_notes,\n            \"requires_human_signoff\": FALSE,\n            \"timestamp\": CURRENT_TIMESTAMP()\n        }\n    ELSE\n        LOG_EVENT(\"ACTION_APPROVE\", \"Safe operating thresholds confirmed\", risk_score)\n        RETURN {\n            \"decision\": \"SEV1_OUTAGE_WAR_ROOM\",\n            \"score\": risk_score,\n            \"evidence\": [\"All baseline validation tests passed within nominal tolerance\"],\n            \"requires_human_signoff\": FALSE,\n            \"timestamp\": CURRENT_TIMESTAMP()\n        }\n    END IF\nEND FUNCTION",
